testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarConfiguracao } from './solution.mjs';

test('sem argumentos devolve a configuração padrão completa', () => {
  assert.deepEqual(criarConfiguracao(), {
    porta: 3000,
    ambiente: 'desenvolvimento',
    logDetalhado: false,
  });
});

test('opções parciais: o que não foi passado fica com o padrão', () => {
  const config = criarConfiguracao({ porta: 8080 });
  assert.deepEqual(config, {
    porta: 8080,
    ambiente: 'desenvolvimento',
    logDetalhado: false,
  });
  const emProducao = criarConfiguracao({ ambiente: 'producao', logDetalhado: true });
  assert.deepEqual(emProducao, {
    porta: 3000,
    ambiente: 'producao',
    logDetalhado: true,
  });
});

test('cada chamada devolve um objeto NOVO e independente', () => {
  const primeira = criarConfiguracao();
  const segunda = criarConfiguracao();
  primeira.porta = 9999;
  assert.equal(segunda.porta, 3000);
  assert.notEqual(primeira, segunda);
});

test('validação: porta e ambiente inválidos lançam erro', () => {
  criarConfiguracao({ porta: 1 }); // válido não lança
  assert.throws(() => criarConfiguracao({ porta: 0 }));
  assert.throws(() => criarConfiguracao({ porta: 70000 }));
  assert.throws(() => criarConfiguracao({ ambiente: 'hack' }));
  assert.throws(() => criarConfiguracao('não é objeto'));
});

solutionCode:
// A factory cria objetos completos a partir de uma configuração parcial.
export function criarConfiguracao(opcoes = {}) {
  if (typeof opcoes !== 'object' || opcoes === null) {
    throw new Error('opções precisa ser um objeto');
  }

  const ambienteValido = ['desenvolvimento', 'producao', 'teste'];
  const porta = opcoes.porta === undefined ? 3000 : opcoes.porta;
  const ambiente = opcoes.ambiente === undefined ? 'desenvolvimento' : opcoes.ambiente;

  if (!Number.isInteger(porta) || porta < 1 || porta > 65535) {
    throw new Error('porta precisa ser um inteiro entre 1 e 65535');
  }
  if (!ambienteValido.includes(ambiente)) {
    throw new Error('ambiente precisa ser desenvolvimento, producao ou teste');
  }

  // Objeto NOVO a cada chamada: duas chamadas não compartilham nada.
  return {
    porta,
    ambiente,
    logDetalhado: opcoes.logDetalhado === undefined ? false : opcoes.logDetalhado,
  };
}
